// 정답이 항상 첫 번째 보기에 오지 않도록 생성 시점에 결정론적으로 위치를 분산한다.
// (런타임에도 questionConverter가 보기를 한 번 더 무작위로 섞지만, seed 자체도 분산해 두어
//  관리자 미리보기, 문항 목록 등 셔플을 거치지 않는 경로에서도 "정답은 항상 1번" 편향이 없게 한다.)
export const seedGrade6V7English: QuestionSeed[] = RAW_G6V7_EN.map((q, i) => {
  if (q.question_type !== 'multiple_choice' || !Array.isArray(q.options) || q.options.length < 2) return q;
  const opts = [...q.options];
  const ci = opts.indexOf(q.correct_answer);
  if (ci < 0) return q;
  const target = i % opts.length; // 0,1,2,3 순환 배치
  if (target === ci) return q;
  const [ans] = opts.splice(ci, 1);
  opts.splice(target, 0, ans);
  return { ...q, options: opts };
});
